gaf3(){return"3. \u6211\u4eec\u4fdd\u7559\u672c\u534f\u8bae\u7684\u5386\u53f2\u7248\u672c,\u60a8\u53ef\u901a\u8fc7\u7b2c\u5341\u56db\u7ae0\u7684\u8054\u7cfb\u65b9\u5f0f\u7d22\u53d6\u3002"},
gaf4(){return"4. \u5e73\u53f0\u5411\u60a8\u53d1\u51fa\u7684\u901a\u77e5,\u53ef\u4ee5\u901a\u8fc7 App \u5185\u516c\u544a\u3001\u7cfb\u7edf\u901a\u77e5\u3001\u9875\u9762\u63d0\u793a\u3001\u60a8\u7ed1\u5b9a\u7684\u624b\u673a\u53f7\u6216\u7535\u5b50\u90ae\u7bb1\u7b49\u65b9\u5f0f\u4f5c\u51fa,\u81ea\u53d1\u5e03\u6216\u53d1\u9001\u4e4b\u65e5\u89c6\u4e3a\u9001\u8fbe;\u60a8\u5411\u5e73\u53f0\u53d1\u51fa\u7684\u901a\u77e5,\u5e94\u901a\u8fc7\u7b2c\u5341\u56db\u7ae0\u516c\u5e03\u7684\u8054\u7cfb\u65b9\u5f0f\u4f5c\u51fa\u3002"},
gafc(){return"\u5341\u4e09\u3001\u6cd5\u5f8b\u9002\u7528\u4e0e\u4e89\u8bae\u89e3\u51b3"},
gaf6(){return"1. \u672c\u534f\u8bae\u7684\u8ba2\u7acb\u3001\u6548\u529b\u3001\u89e3\u91ca\u4e0e\u4e89\u8bae\u89e3\u51b3,\u9002\u7528\u4e2d\u534e\u4eba\u6c11\u5171\u548c\u56fd(\u4e3a\u672c\u534f\u8bae\u4e4b\u76ee\u7684,\u4e0d\u542b\u6e2f\u6fb3\u53f0\u5730\u533a)\u6cd5\u5f8b\u3002"},
gaf7(){return"2. \u56e0\u672c\u534f\u8bae\u4ea7\u751f\u7684\u4e89\u8bae,\u53cc\u65b9\u5e94\u53cb\u597d\u534f\u5546;\u534f\u5546\u4e0d\u6210\u7684,\u4efb\u4f55\u4e00\u65b9\u5747\u53ef\u5411\u3010\u516c\u53f8\u6ce8\u518c\u5730\u5f85\u5b9a\u540e\u586b\u5199\u3011\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\u63d0\u8d77\u8bc9\u8bbc\u3002"},
gaf8(){return"3. \u672c\u534f\u8bae\u4efb\u4e00\u6761\u6b3e\u88ab\u8ba4\u5b9a\u65e0\u6548\u6216\u4e0d\u53ef\u6267\u884c\u7684,\u4e0d\u5f71\u54cd\u5176\u4f59\u6761\u6b3e\u7684\u6548\u529b\u3002"},
gaf9(){return"4. \u672c\u534f\u8bae\u6807\u9898\u4ec5\u4e3a\u65b9\u4fbf\u9605\u8bfb\u800c\u8bbe,\u4e0d\u4f5c\u4e3a\u89e3\u91ca\u6761\u6b3e\u542b\u4e49\u7684\u4f9d\u636e\u3002"},
gafa(){return"5. \u60a8\u4e0e\u5e73\u53f0\u5747\u4e3a\u72ec\u7acb\u4e3b\u4f53,\u672c\u534f\u8bae\u4e0d\u5728\u53cc\u65b9\u4e4b\u95f4\u6784\u6210\u5408\u4f19\u3001\u4ee3\u7406\u3001\u96c7\u4f63\u6216\u62c5\u4fdd\u5173\u7cfb\u3002"},
gafb(){return"6. \u672c\u534f\u8bae\u53ca\u5176\u7ec4\u6210\u6587\u4ef6\u6784\u6210\u53cc\u65b9\u5c31\u76f8\u5173\u4e8b\u9879\u7684\u5b8c\u6574\u7ea6\u5b9a\u3002"},
gafg(){return"\u5341\u56db\u3001\u8054\u7cfb\u6211\u4eec"},
gafd(){return"\u8fd0\u8425\u8005:\u3010\u516c\u53f8\u540d\u79f0\u5f85\u6ce8\u518c\u540e\u586b\u5199\u3011"},
gafe(){return"\u8054\u7cfb\u90ae\u7bb1:\u3010\u8054\u7cfb\u90ae\u7bb1\u5f85\u586b\u5199 \u2014\u2014 \u4e0a\u7ebf\u524d\u5fc5\u987b\u66ff\u6362\u4e3a\u771f\u5b9e\u53ef\u8fbe\u90ae\u7bb1,\u4e0e\u5e73\u53f0\u516c\u7ea6\u9875\u3001\u9690\u79c1\u653f\u7b56\u540c\u4e00\u4e2a\u3011"},
